  if (typeof window === 'undefined' || runtimeScope.__clientLogRelay) return;

  var MAX_BUF = 400;
  var MAX_FLUSH = 200;
  var MAX_MSG = 800;
  // The typed resolver preserves the 15/60-second direct/proxy profiles.
  var FLUSH_MS = clientLogFlushBaseDelayMs(document, location);
