/* ═══════════════════════════════════════════════════════════════════
   log-clean.js — Log Noise Detection & Cleaning (UI layer only)

   The detection heuristic, regex policy, and cleaning algorithms now
   live server-side at lib/log_clean.py exposed via:
     POST /api/v1/logs/clean   { text }   → CleaningResult | {no_noise:true}
     POST /api/v1/logs/compress { text }  → LLM-compressed text

   This file is a *pure render layer* per CLAUDE.md §16:
     - detectLogNoise(text)  →  fetch wrapper, returns the same shape
                                 the old client-side impl returned
     - showLogCleanBanner()  →  DOM render of the structured result
     - applyLogClean()       →  splice cleanedText into the textarea
     - aiCompressLog()       →  LLM compression path (unchanged)
     - previewLogClean()     →  before/after modal

   Going from 740 LOC → ~290 LOC, plus parity with the headless API:
   SDK callers see exactly the same heuristic the UI renders.
   ═══════════════════════════════════════════════════════════════════ */

var _pendingLogClean = null;  // shared with main.js — must be var

// Generation counter used to ignore stale fetches when the user keeps
// typing while a request is in-flight.
let _logCleanReqGen = 0;

/**
 * Detect log noise. Returns a CleaningResult or null.
 * Mirrors the previous client-side function shape, but the policy
 * lives server-side now.
 *
 * Returns a Promise<Object|null>.  Callers that previously did
 *   const result = detectLogNoise(text);
 *   if (result) showLogCleanBanner(result);
 * must now await it (callers in main.js have been updated).
 */
async function detectLogNoise(text) {
  if (!text || typeof text !== 'string') return null;
  // Fast-path: avoid round-trips for trivially short input.
  if (text.split('\n').length < 5) return null;

  const myGen = ++_logCleanReqGen;
  try {
    // Api.logs.clean uses onError:'null' → null on HTTP/network error, matching
    // the old !resp.ok / catch paths (the per-status warn is dropped; the
    // unified client already console.warns failures).
    const body = await Api.logs.clean(text);
    if (myGen !== _logCleanReqGen) return null;  // superseded
    if (!body || body.no_noise) return null;
    if (!body.cleanedText) return null;
    // Server returns dataclass-shaped object; it's already in the
    // shape the old client-side detectLogNoise produced.
    return body;
  } catch (err) {
    if (myGen !== _logCleanReqGen) return null;
    if (typeof debugLog === 'function') {
      debugLog(`[LogClean] detection failed: ${err && err.message}`, 'warn');
    }
    return null;
  }
}

// ── Banner UI ───────────────────────────────────────────────────

function showLogCleanBanner(result) {
  _pendingLogClean = result;
  const banner = document.getElementById('logCleanBanner');
  const info = document.getElementById('logCleanInfo');
  const details = document.getElementById('logCleanDetails');
  if (!banner || !info || !details) return;

  info.innerHTML = t('logClean.banner', {
    chars: result.savedChars.toLocaleString(), pct: result.savedPct,
  });

  const tagsHtml = (result.ops || []).map(op =>
    `<span class="log-clean-tag">• ${_escForBanner(op.desc)}</span>`
  ).join('');
  details.innerHTML = tagsHtml;
  banner.style.display = 'flex';
}

function hideLogCleanBanner() {
  const banner = document.getElementById('logCleanBanner');
  if (banner) banner.style.display = 'none';
  _pendingLogClean = null;
}

function _escForBanner(s) {
  return escapeHtml(s);
}

// ── Active textarea resolution ──────────────────────────────────

function _getActiveTextarea() {
  return document.getElementById('userInput');
}

// ── Rule-based replace (uses server-cleaned text) ───────────────

function applyLogClean() {
  if (!_pendingLogClean) return;
  const input = _getActiveTextarea();
  if (!input) return;
  input.value = input.value.replace(
    _pendingLogClean.originalText,
    _pendingLogClean.cleanedText,
  );
  input.style.height = 'auto';
  input.style.height = Math.min(input.scrollHeight, 200) + 'px';
  if (typeof debugLog === 'function') {
    debugLog(
      `Log noise cleaned: saved ${_pendingLogClean.savedChars} chars` +
      ` (${_pendingLogClean.savedPct}%)`,
      'success',
    );
  }
  hideLogCleanBanner();
}

// ── LLM compression path (unchanged endpoint) ───────────────────

async function aiCompressLog() {
  if (!_pendingLogClean) return;
  const btn = document.getElementById('aiCompressBtn');
  if (!btn) return;
  const originalText = _pendingLogClean.originalText;

  btn.disabled = true;
  const origLabel = btn.innerHTML;
  btn.innerHTML = _aiBtnIconHtml() + ' ' + t('logClean.compressing');

  try {
    // Api.logs.compress throws Error(data.error || 'API error') on non-OK,
    // exactly like the old inline handling.
    const data = await Api.logs.compress(originalText);
    const compressed = data.compressed || '';
    if (!compressed.trim()) throw new Error('LLM returned empty result');

    const input = _getActiveTextarea();
    if (!input) throw new Error('No active textarea');
    input.value = input.value.replace(originalText, compressed);
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 200) + 'px';

    const savedChars = originalText.length - compressed.length;
    const savedPct = Math.round((savedChars / originalText.length) * 100);
    if (typeof debugLog === 'function') {
      debugLog(
        `AI log compress: ${originalText.length} → ${compressed.length}` +
        ` chars (saved ${savedPct}%, model: ${data.model || '?'})`,
        'success',
      );
    }
    hideLogCleanBanner();
  } catch (err) {
    if (typeof debugLog === 'function') {
      debugLog(`[AI Compress] failed: ${err.message}`, 'error');
    }
    btn.innerHTML = _aiBtnIconHtml() + ' ' + t('logClean.retry');
    btn.disabled = false;
  }
}

function _aiBtnIconHtml() {
  return '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" ' +
         'stroke="currentColor" stroke-width="2" stroke-linecap="round" ' +
         'stroke-linejoin="round" style="vertical-align:-1px">' +
         '<rect width="16" height="16" x="4" y="4" rx="2"/>' +
         '<rect width="6" height="6" x="9" y="9" rx="1"/>' +
         '<path d="M15 2v2"/><path d="M15 20v2"/>' +
         '<path d="M2 15h2"/><path d="M2 9h2"/>' +
         '<path d="M20 15h2"/><path d="M20 9h2"/>' +
         '<path d="M9 2v2"/><path d="M9 20v2"/></svg>';
}

// ── Before/after preview modal ──────────────────────────────────

function previewLogClean() {
  if (!_pendingLogClean) return;
  const r = _pendingLogClean;
  const beforeLen = r.originalText.length;
  const afterLen = r.cleanedText.length;

  const breakdownHtml =
    '<div class="log-clean-breakdown">' +
    (r.ops || []).map(op =>
      '<div class="log-clean-breakdown-item">' +
        '<span class="log-clean-breakdown-icon">•</span>' +
        '<span>' + _escForBanner(op.desc) + '</span>' +
      '</div>'
    ).join('') +
    '</div>';

  const _esc = escapeHtml;

  const previewHtml = `
    <div class="log-clean-compare">
      ${breakdownHtml}
      <div class="log-clean-section">
        <div class="log-clean-section-header">
          <span class="log-clean-section-title">${_esc(t('logClean.before'))}</span>
          <span class="log-clean-section-meta">${_esc(t('logClean.metaBefore', { chars: beforeLen.toLocaleString(), lines: r.totalLines }))}</span>
        </div>
        <pre class="log-clean-code">${_esc(r.originalText.slice(0, 3000))}${beforeLen > 3000 ? '\n... (' + (beforeLen - 3000).toLocaleString() + ' more chars)' : ''}</pre>
      </div>
      <div class="log-clean-section">
        <div class="log-clean-section-header">
          <span class="log-clean-section-title">${_esc(t('logClean.after'))}</span>
          <span class="log-clean-section-meta">${_esc(t('logClean.metaAfter', { chars: afterLen.toLocaleString(), pct: r.savedPct }))}</span>
        </div>
        <pre class="log-clean-code">${_esc(r.cleanedText.slice(0, 3000))}${afterLen > 3000 ? '\n... (' + (afterLen - 3000).toLocaleString() + ' more chars)' : ''}</pre>
      </div>
    </div>`;

  const previewBody = document.getElementById('previewBody');
  const previewModal = document.getElementById('previewModal');
  if (!previewBody || !previewModal) return;
  previewBody.innerHTML =
    `<div class="preview-text-panel" style="width:min(900px,90vw)">` +
    `<div class="preview-text-header">` +
    `<span class="preview-text-title">${_esc(t('logClean.previewTitle'))}</span>` +
    `<span class="preview-text-meta">${_esc(t('logClean.previewMeta', { chars: r.savedChars.toLocaleString(), pct: r.savedPct }))}</span>` +
    `</div>` +
    `<div style="padding:16px 20px;overflow-y:auto;max-height:calc(85vh - 60px)">${previewHtml}</div>` +
    `</div>`;
  previewModal.classList.add('open');
}

// Expose for cross-script access (settings/main.js attach to globals).
runtimeScope.detectLogNoise = detectLogNoise;
runtimeScope.showLogCleanBanner = showLogCleanBanner;
runtimeScope.hideLogCleanBanner = hideLogCleanBanner;
runtimeScope.applyLogClean = applyLogClean;
runtimeScope.aiCompressLog = aiCompressLog;
runtimeScope.previewLogClean = previewLogClean;
/* ===== migrated source: translation.js ===== */
/* Async translation application adapter.
 *
 * The translation worker commits completed/skipped facts to the backend Turn
 * with CAS. This module owns only task initiation, polling and lifecycle-local
 * presentation; it never mutates a projected message or TurnStore document.
 */

const _TRANSLATE_POLL_FAST_DELAY = 1000;
const _TRANSLATE_POLL_SLOW_DELAY = 2500;
const _translationTasksByTurn = new Map();
const _translationPollersByTask = new Map();

const _UILANG_TO_TARGET = {
  zh: 'Chinese', 'zh-cn': 'Chinese', 'zh-tw': 'Chinese',
  en: 'English', ja: 'Japanese', ko: 'Korean',
  fr: 'French', de: 'German', es: 'Spanish', ru: 'Russian',
};
const _TARGET_TO_CODE = {
  Chinese: 'zh', English: 'en', Japanese: 'ja', Korean: 'ko',
  French: 'fr', German: 'de', Spanish: 'es', Russian: 'ru',
};

function _translationTaskKey(convId, turnId) {
  return String(convId || '') + ':' + String(turnId || '');
}

function _uiTranslateTarget() {
  const language = (typeof _i18nLang !== 'undefined' && _i18nLang)
    ? String(_i18nLang).toLowerCase() : 'zh';
  return _UILANG_TO_TARGET[language] || 'Chinese';
}

async function _isAlreadyChinese(text) {
  if (!text || typeof text !== 'string' || text.replace(/\s+/g, '').length < 8) {
    return false;
  }
  const result = await Api.text.detectLanguage(text);
  return Boolean(result?.is_chinese);
}

async function _isAlreadyInTarget(text, targetLanguage) {
  if (!text || typeof text !== 'string' || text.replace(/\s+/g, '').length < 8) {
    return false;
  }
  const expected = _TARGET_TO_CODE[targetLanguage];
  if (!expected) return false;
  const result = await Api.text.detectLanguage(text, { forceFasttext: true });
  return result?.detected?.code === expected;
}

/* Retained generic (non-conversation) translation client used by project and
 * stream helpers. It returns text and owns no conversation state. */
async function _callTranslateAPI(text, targetLang, sourceLang) {
  const result = await Api.translate.run({ text, targetLang, sourceLang });
  if (!result?._ok) {
    const detail = (typeof errorEnvelopeMessage === 'function'
      ? errorEnvelopeMessage(result?.error) : '')
      || (typeof result?.error === 'string' ? result.error : '')
      || 'Translation failed';
    throw new Error(detail);
  }
  return result.translated;
}

function _translationTurn(convId, turnId) {
  return runtimeScope.ConversationTurnStore?.ensureRuntimeStore?.(convId)
    ?.getState?.().turnsById?.[turnId] || null;
}

function _setTranslationActivity(convId, turnId, activity) {
  runtimeScope.ConversationSurfacePresentation?.setTranslationActivity?.(
    convId, turnId, activity || null,
  );
}

async function _runManualTurnTranslation(conv, turnId, sourceText) {
  if (!conv || !turnId || !String(sourceText || '').trim()) return;
  _setTranslationActivity(conv.id, turnId, {
    status: 'pending', message: 'Translating…',
  });
  try {
    const alreadyChinese = await _isAlreadyChinese(sourceText);
    await _runTranslationPipeline(conv, turnId, {
      sourceLang: '',
      targetLang: alreadyChinese ? 'English' : 'Chinese',
      field: 'translatedContent',
      skipTargetProbe: true,
    });
  } catch (error) {
    const messageText = error?.message || 'Translation failed';
    _setTranslationActivity(conv.id, turnId, {
      status: 'failed', message: messageText, error: messageText,
    });
    if (typeof showToast === 'function') showToast(messageText, 'error');
  }
}

function _translationErrorText(result) {
  return (typeof errorEnvelopeMessage === 'function'
    ? errorEnvelopeMessage(result?.error) : '')
    || (typeof result?.error === 'string' ? result.error : '')
    || 'Translation failed';
}

function _translationPendingActivity(frame) {
  const partial = typeof frame?.partial === 'string' ? frame.partial : undefined;
  const partialByRound = frame?.partialByRound
      && typeof frame.partialByRound === 'object'
    ? frame.partialByRound : undefined;
  return {
    status: 'pending',
    message: frame?.statusMessage || 'Translating…',
    ...(partial !== undefined ? { partial } : {}),
    ...(partialByRound !== undefined ? { partialByRound } : {}),
  };
}

async function _hydrateTranslatedTurn(conv) {
  if (!conv) return;
  await runtimeScope.ConversationTurnStore?.hydrateConversation?.(conv);
}

async function _startTranslateTask(
  text, targetLang, sourceLang, convId, turnId, field, msgId,
) {
  if (convId && !turnId) {
    throw new Error(
      'Message is not attached to an authoritative turn; reload and retry.',
    );
  }
  const result = await Api.translate.start({
    text, targetLang, sourceLang, convId, turnId, field,
    ...(msgId ? { msgId } : {}),
  });
  if (!result?.taskId) throw new Error('Translation task did not start');
  return result.taskId;
}

async function _pollTranslateTask(taskId) {
  return Api.translate.poll(taskId);
}

async function _pollTranslateTaskBatch(taskIds) {
  if (!taskIds.length) return [];
  const results = await Api.translate.pollBatch(taskIds);
  return Array.isArray(results) ? results : [];
}

async function _settleTranslationTask(conv, turnId, taskId, result) {
  const key = _translationTaskKey(conv.id, turnId);
  const current = _translationTasksByTurn.get(key);
  if (current?.taskId && current.taskId !== taskId) return false;
  _translationTasksByTurn.delete(key);
  if (result?.status === 'done' || result?.noop === true) {
    _setTranslationActivity(conv.id, turnId, null);
    await _hydrateTranslatedTurn(conv);
    return true;
  }
  const error = _translationErrorText(result);
  _setTranslationActivity(conv.id, turnId, {
    status: 'failed', message: error, error,
  });
  if (typeof showToast === 'function') showToast(error, 'error');
  return false;
}

async function _runTranslationPollLoop({
  conv, turnId, taskId, field, sourceLang, targetLang,
}) {
  const taskKey = _translationTaskKey(conv.id, turnId);
  let pollCount = 0;
  while (_translationTasksByTurn.get(taskKey)?.taskId === taskId) {
    const delay = pollCount < 5
      ? _TRANSLATE_POLL_FAST_DELAY : _TRANSLATE_POLL_SLOW_DELAY;
    pollCount += 1;
    await new Promise((resolve) => setTimeout(resolve, delay));
    // A terminal push may settle the task while this poller is sleeping.
    // Re-check ownership before issuing a redundant request.
    if (_translationTasksByTurn.get(taskKey)?.taskId !== taskId) return;
    const result = await _pollTranslateTask(taskId);
    if (result?.status === 'running') {
      _setTranslationActivity(
        conv.id, turnId, _translationPendingActivity(result),
      );
      continue;
    }
    if (result?.status === 'not_found') {
      try { await _hydrateTranslatedTurn(conv); }
      catch (_ignored) { /* terminal presentation below remains actionable */ }
    }
    await _settleTranslationTask(conv, turnId, taskId, result);
    return;
  }
}

function _pollTranslationUntilSettled(options) {
  const taskId = options?.taskId;
  const existing = _translationPollersByTask.get(taskId);
  if (existing) return existing;

  const poller = _runTranslationPollLoop(options);
  _translationPollersByTask.set(taskId, poller);
  const release = () => {
    if (_translationPollersByTask.get(taskId) === poller) {
      _translationPollersByTask.delete(taskId);
    }
  };
  // Attach both handlers so cleanup itself cannot create an unhandled
  // rejection. The original poller remains the caller-visible authority.
  void poller.then(release, release);
  return poller;
}

async function _markTranslationSkipped(conv, turn, targetLanguage) {
  const projection = {
    ...turn.projection,
    translation: {
      status: 'skipped',
      skippedReason: 'already_target_language',
      targetLanguage,
    },
  };
  await runtimeScope.ConversationTurnStore.updateConversationTurn(
    conv, turn.turnId, projection,
  );
}

async function _runTranslationPipeline(conv, turnId, options) {
  if (!conv) return;
  const turn = typeof turnId === 'string'
    ? _translationTurn(conv.id, turnId) : null;
  if (!turn) {
    const error = 'Message is not attached to an authoritative turn; reload and retry.';
    _setTranslationActivity(conv.id, turnId, null);
    if (typeof showToast === 'function') showToast(error, 'error');
    return;
  }
  const field = options?.field || 'translatedContent';
  const sourceText = options?.text != null
    ? String(options.text) : String(turn.projection.content || '');
  if (!sourceText.trim()) return;
  const targetLanguage = options?.targetLang || _uiTranslateTarget();
  const sourceLanguage = options?.sourceLang || '';
  const key = _translationTaskKey(conv.id, turnId);

  if (!options?.existingTaskId && !options?.skipTargetProbe
      && await _isAlreadyInTarget(sourceText, targetLanguage)) {
    try {
      await _markTranslationSkipped(conv, turn, targetLanguage);
      _setTranslationActivity(conv.id, turnId, null);
    } catch (error) {
      _setTranslationActivity(conv.id, turnId, {
        status: 'failed', message: error?.message || 'Translation failed',
        error: error?.message || error,
      });
    }
    return;
  }

  if (!options?.existingTaskId
      && !TRANSLATION_CLAIMS.claim(conv.id, turnId)) return;

  try {
    const taskId = options?.existingTaskId || await _startTranslateTask(
      sourceText,
      targetLanguage,
      sourceLanguage,
      conv.id,
      turnId,
      field,
      '',
    );
    _translationTasksByTurn.set(key, {
      taskId, field, sourceLang: sourceLanguage, targetLang: targetLanguage,
    });
    _setTranslationActivity(conv.id, turnId, {
      status: 'pending', message: 'Translating…',
    });
    await _pollTranslationUntilSettled({
      conv, turnId, taskId, field,
      sourceLang: sourceLanguage, targetLang: targetLanguage,
    });
  } catch (error) {
    _translationTasksByTurn.delete(key);
    const messageText = error?.message || 'Translation failed';
    _setTranslationActivity(conv.id, turnId, {
      status: 'failed', message: messageText, error: messageText,
    });
    if (typeof showToast === 'function') showToast(messageText, 'error');
  } finally {
    TRANSLATION_CLAIMS.release(conv.id, turnId);
  }
}

/* Page/tab activation only resumes tasks initiated in this browser lifetime.
 * Durable results converge independently through Conversation Sync v3. */
async function _resumePendingTranslations(convId) {
  const conv = conversations.find((item) => item?.id === convId);
  if (!conv) return;
  const pending = [..._translationTasksByTurn.entries()]
    .filter(([key]) => key.startsWith(String(convId) + ':'));
  if (!pending.length) return;
  const results = await _pollTranslateTaskBatch(
    pending.map(([, task]) => task.taskId),
  );
  const byTask = new Map(results.map((result) => [result.taskId, result]));
  for (const [key, task] of pending) {
    const turnId = key.slice(String(convId).length + 1);
    const result = byTask.get(task.taskId);
    if (result?.status === 'running') {
      _setTranslationActivity(
        convId, turnId, _translationPendingActivity(result),
      );
      void _pollTranslationUntilSettled({
        conv, turnId, taskId: task.taskId, field: task.field,
        sourceLang: task.sourceLang, targetLang: task.targetLang,
      });
    } else {
      await _settleTranslationTask(
        conv, turnId, task.taskId,
        result || { status: 'not_found', error: 'Translation task expired' },
      );
    }
  }
}

(function wireServerTranslationProjection() {
  if (typeof pushSubscribe !== 'function'
      || runtimeScope.__translatePushWired) return;
  runtimeScope.__translatePushWired = true;
  pushSubscribe('translate', '*', async (frame) => {
    try {
      if (!frame?.convId || !frame.turnId) return;
      const conv = conversations.find((item) => item?.id === frame.convId);
      if (!conv) return;
      if (frame.status === 'running' || frame.type === 'running') {
        _setTranslationActivity(
          frame.convId, frame.turnId, _translationPendingActivity(frame),
        );
        return;
      }
      if (frame.status === 'done' || frame.type === 'done'
          || frame.noop === true) {
        _setTranslationActivity(frame.convId, frame.turnId, null);
        _translationTasksByTurn.delete(
          _translationTaskKey(frame.convId, frame.turnId),
        );
        await _hydrateTranslatedTurn(conv);
        return;
      }
      if (frame.status === 'error' || frame.type === 'error') {
        _translationTasksByTurn.delete(
          _translationTaskKey(frame.convId, frame.turnId),
        );
        const error = _translationErrorText(frame);
        _setTranslationActivity(frame.convId, frame.turnId, {
          status: 'failed', message: error, error,
        });
        return;
      }
      if (frame.status === 'aborted' || frame.type === 'aborted') {
        _translationTasksByTurn.delete(
          _translationTaskKey(frame.convId, frame.turnId),
        );
        _setTranslationActivity(frame.convId, frame.turnId, null);
      }
    } catch (error) {
      console.debug(
        '[Translate] authority adoption failed:', error?.message || error,
      );
    }
  });
})();
